namespace sarif.export.props;





using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.util;
using ghidra.util;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;
using sarif.export;
using sarif.export;
using sarif.managers;

public class SarifPropertyMapWriter : AbstractExtWriter {

	List<PropertyMap<object>> maps;
	Program program;
	AddressSetView set;

	public SarifPropertyMapWriter(List<PropertyMap<object>> request, Program program, AddressSetView set, Writer baseWriter)
    : base(baseWriter)
    {
		this.maps = request;
		this.program = program;
		this.set = set;
	}

	/* @Override */
	protected void genRoot(TaskMonitor monitor)
    {
		genMap(monitor);
		root.add("properties", objects);
	}

	private void genMap(TaskMonitor monitor)
    {
		monitor.initialize(maps.size());
		foreach (PropertyMap<object> map in maps) {
			if (map is VoidPropertyMap) {
				genVoidMap((VoidPropertyMap) map, monitor);
			} else if (map is IntPropertyMap) {
				genIntMap((IntPropertyMap) map, monitor);
			} else if (map is LongPropertyMap) {
				genLongMap((LongPropertyMap) map, monitor);
			} else if (map is StringPropertyMap) {
				genStringMap((StringPropertyMap) map, monitor);
			} else if (map is ObjectPropertyMap) {
				genObjectMap((ObjectPropertyMap<object>) map, monitor);
			}
		}
	}

	private void genVoidMap(VoidPropertyMap map, TaskMonitor monitor)
    {
		AddressIterator iter = set != null ? map.getPropertyIterator(set) : map.getPropertyIterator();
		while (iter.hasNext()) {
			monitor.checkCancelled();
			Address addr = iter.next();
			ExtProperty isf = new ExtProperty(map.getName(), "void", null);
			SarifObject sarif = new SarifObject(PropertiesSarifMgr.SUBKEY, PropertiesSarifMgr.KEY, getTree(isf), addr,
					addr);
			objects.add(getTree(sarif));
			monitor.increment();
		}
	}

	private void genIntMap(IntPropertyMap map, TaskMonitor monitor)
    {
		AddressIterator iter = set != null ? map.getPropertyIterator(set) : map.getPropertyIterator();
		while (iter.hasNext()) {
			monitor.checkCancelled();
			try {
				Address addr = iter.next();
				int value = map.getInt(addr);
				ExtProperty isf = new ExtProperty(map.getName(), "int", Integer.toHexString(value));
				SarifObject sarif = new SarifObject(PropertiesSarifMgr.SUBKEY, PropertiesSarifMgr.KEY, getTree(isf),
						addr, addr);
				objects.add(getTree(sarif));
			} catch (NoValueException e) {
				// skip
			}
		}
	}

	private void genLongMap(LongPropertyMap map, TaskMonitor monitor)
    {
		AddressIterator iter = set != null ? map.getPropertyIterator(set) : map.getPropertyIterator();
		while (iter.hasNext()) {
			monitor.checkCancelled();
			try {
				Address addr = iter.next();
				long value = map.getLong(addr);
				ExtProperty isf = new ExtProperty(map.getName(), "long", Long.toHexString(value));
				SarifObject sarif = new SarifObject(PropertiesSarifMgr.SUBKEY, PropertiesSarifMgr.KEY, getTree(isf),
						addr, addr);
				objects.add(getTree(sarif));
			} catch (NoValueException e) {
				// skip
			}
		}

	}

	private void genStringMap(StringPropertyMap map, TaskMonitor monitor)
    {
		AddressIterator iter = set != null ? map.getPropertyIterator(set) : map.getPropertyIterator();
		while (iter.hasNext()) {
			monitor.checkCancelled();
			Address addr = iter.next();
			string value = map.getString(addr);
			ExtProperty isf = new ExtProperty(map.getName(), "string", value);
			SarifObject sarif = new SarifObject(PropertiesSarifMgr.SUBKEY, PropertiesSarifMgr.KEY, getTree(isf), addr,
					addr);
			objects.add(getTree(sarif));
		}
	}
	

	private void genObjectMap(ObjectPropertyMap<object> map, TaskMonitor monitor)
    {
		AddressIterator iter = set != null ? map.getPropertyIterator(set) : map.getPropertyIterator();
		while (iter.hasNext()) {
			monitor.checkCancelled();
			Address addr = iter.next();
			object value = map.get(addr);
			ExtProperty isf;
			if (value is SaveablePoint) {
				isf = new ExtProperty(map.getName(), "point", value.toString());
			}
			else if (value is SaveableColor) {
				isf = new ExtProperty(map.getName(), "color", value.toString());
			}
			else {
				return;
			}
			SarifObject sarif = new SarifObject(PropertiesSarifMgr.SUBKEY, PropertiesSarifMgr.KEY, getTree(isf), addr,
					addr);
			objects.add(getTree(sarif));
		}
	}

}
